'use strict';
(()=>{const app=document.querySelector('#marketing-app'),alert=document.querySelector('#marketing-alert');let state=null,tab='settings',remote=[],busy=false,audience=null,audiencePreview=null,testImage='';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const say=t=>alert.textContent=t;
async function api(path,body){const r=await fetch('/api/marketing/'+path,{credentials:'same-origin',cache:'no-store',...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});const data=await r.json();if(!r.ok)throw Error(data.error||'تعذر تنفيذ الطلب.');return data;}
const field=(name,label,value='',extra='')=>`<label>${label}<input name="${name}" value="${esc(value)}" ${extra}></label>`;
const btn=(a,t,disabled=false)=>`<button class="info-button" type="button" data-marketing="${a}" ${disabled?'disabled':''}>${t}</button>`;
function settings(){const c=state.settings;return `<div class="marketing-grid"><section class="marketing-panel"><h2>ربط حساب ميتا</h2><span class="marketing-status">${state.ready?'بيانات الربط مكتملة · اختبر الاتصال':'بانتظار بيانات الربط'}</span><form id="marketing-settings">${field('appId','معرّف تطبيق ميتا · لرفع صور القوالب',c.appId,'inputmode="numeric" dir="ltr"')}${field('wabaId','معرّف حساب WhatsApp Business',c.wabaId,'required inputmode="numeric" dir="ltr"')}${field('phoneId','معرّف رقم الهاتف',c.phoneId,'required inputmode="numeric" dir="ltr"')}${field('version','إصدار Graph API',c.version,'required placeholder="الإصدار الظاهر في تطبيق ميتا" dir="ltr"')}<button class="info-button gold">حفظ إعدادات الربط</button></form><div class="marketing-actions">${btn('check','اختبار الاتصال',!state.ready)}</div></section><section class="marketing-panel"><h2>تجربة الإدارة أولًا</h2><p>القسم مفتوح للإدارة فقط. يظل تسويق واتساب مقفلًا في لوحة صاحب النشاط خلال التطوير.</p><p>الرمز السري محفوظ في الاستضافة باسم <b dir="ltr">META_WHATSAPP_TOKEN</b>، ولا يظهر في المتصفح.</p><span class="marketing-status">${state.tokenConfigured?'الرمز السري موجود':'الرمز السري لم يُضف بعد'}</span><p>يستخدم النشاط حسابه ورقمه لدى ميتا، ويسدد تكلفة الرسائل من حسابه. رجعة توفر إدارة القوالب والحملات.</p><a class="info-button" href="https://developers.facebook.com/apps/" target="_blank" rel="noopener">فتح تطبيقات ميتا ↗</a></section></div>`;}
function drafts(kind){if(kind==='template')return window.MarketingTemplateEditor.html(state.templates);const templates=kind==='template',rows=templates?state.templates:state.campaigns;return `<div class="marketing-grid"><section class="marketing-panel"><h2>${templates?'قالب جديد':'مسودة حملة'}</h2><p>${templates?'ابدأ بنص ثابت للاختبار. اعتماد القالب يتم لدى ميتا.':'احفظ فكرة الحملة ونصها أولًا. الإرسال الجماعي والجدولة سيُفتحان بعد اختبار الربط والتسليم والموافقات.'}</p><form id="marketing-draft"><input type="hidden" name="kind" value="${kind}">${field('title','العنوان الداخلي','','required maxlength="100"')}<label>الاستخدام<select name="purpose"><option value="loyalty">بطاقات رجعة · زيارات ومكافآت</option><option value="general">عام · عروض وتذكيرات خارج البطاقات</option></select></label>${field('name','اسم قالب ميتا','','pattern="[a-z0-9_]+" placeholder="rijaa_offer" dir="ltr"')}${field('language','لغة القالب','ar','required dir="ltr"')}<label>نص الرسالة<textarea name="body" required maxlength="1024" placeholder="اكتب رسالة واضحة ومختصرة"></textarea></label><div class="marketing-preview" id="marketing-preview">معاينة نص الرسالة</div><button class="info-button gold">حفظ المسودة</button></form></section><section class="marketing-panel"><h2>${templates?'القوالب المحفوظة':'الحملات المحفوظة'}</h2>${rows.map(d=>`<article class="marketing-draft"><b>${esc(d.title)}</b><small class="marketing-meta"> · ${d.purpose==='loyalty'?'ولاء':'عام'} · مسودة</small><p>${esc(d.body)}</p>${templates?`<button class="info-button" data-marketing="submit" data-id="${esc(d.id)}" ${!state.ready?'disabled':''}>إرسال القالب لمراجعة ميتا</button>`:''}</article>`).join('')||'<p class="marketing-empty">لا توجد مسودات محفوظة.</p>'}</section></div>`;}
function testing(){return `<div class="marketing-grid"><section class="marketing-panel"><h2>قوالب ميتا</h2><p>القائمة تعرض أول 100 قالب. اختر قالبًا معتمدًا لتجربته مع الصورة والمتغيرات والأزرار الثابتة.</p>${btn('sync','جلب القوالب من ميتا',!state.ready)}${remote.map(t=>`<div class="marketing-draft"><b dir="ltr">${esc(t.name)}</b><span> · ${esc(t.language)} · ${esc(t.status)}</span><p>${esc(t.components?.find(c=>c.type==='BODY')?.text||'')}</p></div>`).join('')}</section><section class="marketing-panel"><h2>إرسال رسالة تجربة واحدة</h2><p>استخدم رقمك أو رقمًا وافق على التجربة. قد تُحسب تكلفة رسالة لدى ميتا. قبول الطلب لا يعني أن الرسالة وصلت.</p><form id="marketing-test"><label>قالب معتمد<select name="template" required><option value="">اختر قالبًا بعد جلب القائمة</option>${remote.filter(t=>t.status==='APPROVED').map(t=>`<option value="${esc(t.name+'|'+t.language)}">${esc(t.name+' · '+t.language)}</option>`).join('')}</select></label><div id="marketing-test-components"></div><div id="marketing-test-preview"></div>${field('recipient','رقم التجربة الدولي','','required dir="ltr" placeholder="966…"')}<label><input type="checkbox" name="consent" required> صاحب الرقم وافق على هذه الرسالة التجريبية</label><button class="info-button gold" ${!state.ready?'disabled':''}>مراجعة وإرسال التجربة</button></form></section></div><section class="marketing-panel"><h2>سجل التجارب</h2><div style="overflow:auto"><table class="marketing-table"><thead><tr><th>القالب</th><th>الرقم</th><th>حالة الطلب</th><th>معرّف ميتا</th></tr></thead><tbody>${state.tests.map(t=>`<tr><td>${esc(t.template)}</td><td dir="ltr">${esc(t.recipient)}</td><td>${({accepted:'قُبل لدى ميتا · التسليم غير مؤكد',pending:'قيد التأكيد',unconfirmed:'غير مؤكد · راجع ميتا قبل الإعادة'})[t.status]||esc(t.status)}</td><td dir="ltr">${esc(t.message_id||'—')}</td></tr>`).join('')}</tbody></table></div></section>`;}
function selectedTest(){const value=document.querySelector('#marketing-test select[name="template"]')?.value;return remote.find(t=>t.name+'|'+t.language===value);}
function testPreview(){const t=selectedTest(),slot=document.querySelector('#marketing-test-preview');if(!slot||!t)return;const f=document.querySelector('#marketing-test'),header=t.components?.find(c=>c.type==='HEADER'),body=t.components?.find(c=>c.type==='BODY')?.text||'',samples=[...f.querySelectorAll('[data-test-param]')].map(x=>x.value);slot.innerHTML=window.MarketingTemplateEditor.preview({body,samples,headerType:header?.format||'NONE',header:header?.text,image:testImage,footer:t.components?.find(c=>c.type==='FOOTER')?.text,buttons:t.components?.find(c=>c.type==='BUTTONS')?.buttons||[]});}
function testFields(){const t=selectedTest(),slot=document.querySelector('#marketing-test-components');testImage='';if(!slot)return;if(!t){slot.innerHTML='';return;}const header=t.components?.find(c=>c.type==='HEADER'),body=t.components?.find(c=>c.type==='BODY'),indices=[...new Set([...(body?.text||'').matchAll(/\{\{(\d+)\}\}/g)].map(m=>Number(m[1])))].sort((a,b)=>a-b);slot.innerHTML=(header?.format==='IMAGE'?'<label>صورة رسالة التجربة<input type="file" id="marketing-test-image" accept="image/png,image/jpeg" required></label>':'')+indices.slice(0,5).map((v,i)=>field('param'+v,'قيمة المتغير {{'+v+'}}',body?.example?.body_text?.[0]?.[i]||'','required maxlength="1000" data-test-param')).join('');testPreview();}
app.addEventListener('change',e=>{if(e.target.matches('#marketing-test select[name="template"]'))testFields();if(e.target.id==='marketing-test-image')run(async()=>{testImage=await window.MarketingTemplateEditor.prepare(e.target.files?.[0]);testPreview();say('صورة التجربة جاهزة؛ لم تُرسل إلى ميتا.');});});
function render(){app.innerHTML=`<nav class="marketing-tabs" aria-label="أقسام التسويق">${[['settings','الربط'],['contacts','الأرقام وجهات الاتصال'],['template','القوالب'],['campaign','الحملات'],['test','التجربة والسجل']].map(([id,title])=>`<button class="info-button" data-tab="${id}" aria-selected="${tab===id}">${title}</button>`).join('')}</nav>${tab==='contacts'?window.MarketingContacts.html():tab==='settings'?settings():tab==='test'?testing():drafts(tab)}`;if(tab==='template')window.MarketingTemplateEditor.init();if(tab==='template'&&remote.length)app.insertAdjacentHTML('beforeend','<section class="marketing-panel"><h2>قوالب حساب ميتا</h2>'+remote.map(t=>'<article class="marketing-draft"><b dir="ltr">'+esc(t.name)+'</b><span class="marketing-status">'+esc(t.status)+'</span><p>'+esc(t.components?.find(c=>c.type==='BODY')?.text||'')+'</p></article>').join('')+'</section>');document.dispatchEvent(new CustomEvent('marketing-tab',{detail:tab}));if(tab==='contacts')window.MarketingContacts.load().catch(e=>say(e.message));if(tab==='campaign'&&audience)app.insertAdjacentHTML('beforeend',`<section class="marketing-panel"><h2>قائمة مستلمي الحملة</h2><p>${audience.selected.length} رقم محدد · ${audiencePreview?.eligible||0} بموافقة مسجلة · ${audiencePreview?.excluded||0} مستبعد من الإرسال. تحفظ هذه القائمة مع مسودة الحملة ولا تُرسل تلقائيًا.</p></section>`);}
async function refresh(){state=await api('state');render();}
async function run(fn){if(busy)return;busy=true;try{await fn();}catch(e){say(e.message);}finally{busy=false;}}
app.addEventListener('input',e=>{if(tab==='test')testPreview();if(e.target.name==='body'&&tab!=='template')document.querySelector('#marketing-preview').textContent=e.target.value||'معاينة نص الرسالة';});
app.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.templateEdit){window.MarketingTemplateEditor.load(state.templates.find(d=>d.id===b.dataset.templateEdit));render();return;}if(b.dataset.templatePreset){window.MarketingTemplateEditor.preset(b.dataset.templatePreset);render();return;}if(b.hasAttribute('data-template-new')){window.MarketingTemplateEditor.reset();render();return;}if(b.dataset.tab){if(tab==='template')window.MarketingTemplateEditor.keep();tab=b.dataset.tab;render();return;}const action=b.dataset.marketing;if(!action)return;run(async()=>{if(action==='check'){const r=await api('check',{});say('تم الاتصال بميتا: '+(r.phone.verified_name||r.phone.display_phone_number||r.phone.id));}if(action==='sync'){if(tab==='template')window.MarketingTemplateEditor.keep();remote=(await api('templates',{})).templates;render();say('تم جلب قوالب ميتا.');}if(action==='submit'){if(!confirm('إرسال هذا القالب لمراجعة ميتا؟'))return;await api('template-submit',{id:b.dataset.id,confirm:true});await refresh();say('تم إرسال القالب لمراجعة ميتا. حدّث القائمة لمتابعة الاعتماد.');}});});
app.addEventListener('submit',e=>{e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f));run(async()=>{if(f.getAttribute('id')==='marketing-settings'){await api('settings',d);await refresh();say('تم حفظ معرّفات الربط.');}if(f.getAttribute('id')==='marketing-draft'){if(d.kind==='template')Object.assign(d,window.MarketingTemplateEditor.read());if(d.kind==='campaign'&&audience)d.audience=audience;await api('draft',d);window.MarketingTemplateEditor.reset();await refresh();say('تم حفظ المسودة دون إرسال.');}if(f.getAttribute('id')==='marketing-test'){const [name,language]=d.template.split('|');if(!confirm('إرسال رسالة حقيقية واحدة إلى '+d.recipient+'؟ قد تتحمل تكلفة ميتا.'))return;await api('test',{name,language,recipient:d.recipient,image:testImage,parameters:[...f.querySelectorAll('[data-test-param]')].map(x=>x.value),consent:d.consent==='on',confirm:true});await refresh();say('قبلت ميتا طلب الإرسال. تحقق من وصول الرسالة على الهاتف.');}});});
document.addEventListener('marketing-audience',e=>run(async()=>{audience=e.detail;audiencePreview=await api('audience',audience);tab='campaign';render();say('تم اختيار مستلمي الحملة. احفظ المسودة بعد كتابة النص.');}));
window.MarketingApp={switchTab:id=>{if(!['settings','contacts','template','campaign','test'].includes(id))return;if(tab==='template')window.MarketingTemplateEditor.keep();tab=id;render();}};
refresh().catch(e=>{say(e.message);app.innerHTML='<section class="marketing-panel"><h2>القسم مخصص للإدارة</h2><p>سجّل الدخول بحساب الإدارة للوصول إلى إعدادات التسويق.</p><a class="info-button gold" href="/admin">دخول الإدارة ↗</a></section>';});})();
